function getNewsByCategory($category) {
    global $news, $categories;
    $khCategory = $categories[$category] ?? $category;

    $filteredNews = array_filter($news, function($newsItem) use ($khCategory) {
        return $newsItem['category'] === $khCategory;
    });

    return orderByDate(array_values($filteredNews));
}

function getNewsById($id) {
    global $news;
    foreach ($news as $newsItem) {
        if ($newsItem['id'] == $id) {
            return $newsItem;
        }
    }
    return null;
}

// search function
function searchNews($search = "") {
    global $news;

    // remove spaces
    $search = trim(strtolower($search));

    if ($search == "") {
        return orderByDate($news);
    }

    $results = [];

    foreach ($news as $item) {

        $title = strtolower($item['title']);
        $category = strtolower($item['category']);

        // search by title OR category
        if (
            str_contains($title, $search) ||
            str_contains($category, $search)
        ) {
            $results[] = $item;
        }
    }

    return orderByDate($results);
}

// order news by date
function orderByDate($news) {

    usort($news, function($a, $b) {

        return strtotime($b['date']) - strtotime($a['date']);
    });

    return $news;
}

// truncate title or content
function truncate($text, $number_of_character = 50) {
    $text = (string) $text;
    if (mb_strlen($text, 'UTF-8') > $number_of_character) {
        return htmlspecialchars(mb_substr($text, 0, $number_of_character, 'UTF-8') . "...", ENT_QUOTES, 'UTF-8');
    }

    return htmlspecialchars($text, ENT_QUOTES, 'UTF-8');
}

// format date
function formatKhmerDate($dateString) {
    global $months, $khmerNumbers;

    $timestamp = strtotime($dateString);

    $day = date('d', $timestamp);
    $month = date('m', $timestamp);
    $year = date('Y', $timestamp);
    $time = date('H:i', $timestamp);

    // convert to khmer number
    $day = strtr($day, $khmerNumbers);
    $year = strtr($year, $khmerNumbers);
    $time = strtr($time, $khmerNumbers);

    return "{$day} ខែ {$months[$month]} ឆ្នាំ {$year} ម៉ោង {$time}";
}


function timeAgoKhmer($dateString) {

    global $months, $khmerNumbers;

    $timestamp = strtotime($dateString);
    $currentTime = time();

    $difference = $currentTime - $timestamp;

    // seconds
    if ($difference < 60) {
        $value = strtr($difference, $khmerNumbers);
        return "{$value} វិនាទីមុន";
    }

    // minutes
    elseif ($difference < 3600) {
        $minutes = floor($difference / 60);
        $minutes = strtr($minutes, $khmerNumbers);
        return "{$minutes} នាទីមុន";
    }

    // hours
    elseif ($difference < 86400) {
        $hours = floor($difference / 3600);
        $hours = strtr($hours, $khmerNumbers);
        return "{$hours} ម៉ោងមុន";
    }

    // days
    elseif ($difference < 2592000) {
        $days = floor($difference / 86400);
        $days = strtr($days, $khmerNumbers);
        return "{$days} ថ្ងៃមុន";
    }

    // months
    elseif ($difference < 31536000) {
        $months = floor($difference / 2592000);
        $months = strtr($months, $khmerNumbers);
        return "{$months} ខែមុន";
    }

    // years
    else {
        $years = floor($difference / 31536000);
        $years = strtr($years, $khmerNumbers);
        return "{$years} ឆ្នាំមុន";
    }
}

